package org.apache.rocketmq.store.pop;

import org.junit.Assert;
import org.junit.Test;

public class PopCheckPointTest {

    @Test
    public void testCompareToWithOverflow() {
        // When this.startOffset < other.startOffset, compareTo MUST return negative.
        // Using values that cause long subtraction overflow:
        //   this.startOffset = 0
        //   other.startOffset = Long.MAX_VALUE
        // Correct: 0 - Long.MAX_VALUE = negative value, so compareTo < 0.
        // Buggy: (int)(0 - Long.MAX_VALUE) = (int)(-9223372036854775807) = 1 (positive!)

        PopCheckPoint a = new PopCheckPoint();
        a.setStartOffset(0L);

        PopCheckPoint b = new PopCheckPoint();
        b.setStartOffset(Long.MAX_VALUE);

        int result = a.compareTo(b);
        // compareTo contract: if a < b, result must be negative
        Assert.assertTrue(
            "compareTo should return negative when this.startOffset(0) < other.startOffset(Long.MAX_VALUE), but got: " + result,
            result < 0
        );
    }

    @Test
    public void testCompareToWithOverflowReversed() {
        // Reverse: this.startOffset > other.startOffset, compareTo MUST return positive.
        PopCheckPoint a = new PopCheckPoint();
        a.setStartOffset(Long.MAX_VALUE);

        PopCheckPoint b = new PopCheckPoint();
        b.setStartOffset(0L);

        int result = a.compareTo(b);
        // compareTo contract: if a > b, result must be positive
        Assert.assertTrue(
            "compareTo should return positive when this.startOffset(Long.MAX_VALUE) > other.startOffset(0), but got: " + result,
            result > 0
        );
    }

    @Test
    public void testCompareToWithEqualValues() {
        PopCheckPoint a = new PopCheckPoint();
        a.setStartOffset(Long.MAX_VALUE);

        PopCheckPoint b = new PopCheckPoint();
        b.setStartOffset(Long.MAX_VALUE);

        int result = a.compareTo(b);
        Assert.assertEquals("compareTo should return 0 when startOffsets are equal", 0, result);
    }

    @Test
    public void testCompareToConsistencyWithLongCompare() {
        // compareTo should be consistent with Long.compare semantics
        PopCheckPoint a = new PopCheckPoint();
        a.setStartOffset(1L);

        PopCheckPoint b = new PopCheckPoint();
        b.setStartOffset(Long.MAX_VALUE);

        int expected = Long.compare(1L, Long.MAX_VALUE); // negative
        int actual = a.compareTo(b);

        Assert.assertEquals(
            "compareTo sign should match Long.compare sign for (1, Long.MAX_VALUE)",
            Integer.signum(expected),
            Integer.signum(actual)
        );
    }
}

