            Arrays.asList(mq0, mq1)
        );

        List<MessageQueuePenalizer<MessageQueue>> penalizers = Collections.singletonList(mq -> mq.getQueueId() * 10);
        AtomicInteger startIndex = new AtomicInteger(0);

