package org.apache.rocketmq.broker.pop.orderly;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests for QueueLevelConsumerManager.OrderInfo.isNotAck() method.
 * 
 * This tests the correctness of bit-checking for ack status when offsetIndex >= 64,
 * where Java's long shift wraps (1L << 64 == 1L << 0).
 */
public class QueueLevelConsumerManagerOrderInfoTest {

    /**
     * Test that isNotAck returns true for index 64 when only bit 0 is set.
     * 
     * Bug: 1L << 64 wraps to 1L << 0 in Java, so the buggy code checks bit 0
     * instead of bit 64, returning false (acked) when it should return true (not acked).
     * 
     * Correct behavior: bit 64 is NOT set, so isNotAck(64) should return true.
     */
    @Test
    public void testIsNotAckAtIndex64WithBit0Set() {
        QueueLevelConsumerManager.OrderInfo orderInfo = new QueueLevelConsumerManager.OrderInfo();
        // Set commitOffsetBit = 1, meaning only bit 0 is acked
        orderInfo.setCommitOffsetBit(1L);

        // Bit 64 is NOT set, so message at index 64 should be NOT acked
        // The buggy code does: (1L & (1L << 64)) == 0, but 1L << 64 wraps to 1L << 0 = 1
        // So buggy code: (1L & 1) == 0 -> false (WRONG - says it's acked)
        // Correct: bit 64 is not set -> true (not acked)
        assertTrue("Message at index 64 should be not-acked since bit 64 is not set",
                orderInfo.isNotAck(64));
    }

    /**
     * Test that isNotAck returns true for index 65 when only bit 1 is set.
     * 
     * Bug: 1L << 65 wraps to 1L << 1 in Java, so the buggy code checks bit 1
     * instead of bit 65, returning false (acked) when it should return true (not acked).
     */
    @Test
    public void testIsNotAckAtIndex65WithBit1Set() {
        QueueLevelConsumerManager.OrderInfo orderInfo = new QueueLevelConsumerManager.OrderInfo();
        // Set commitOffsetBit = 2, meaning only bit 1 is acked
        orderInfo.setCommitOffsetBit(2L);

        // Bit 65 is NOT set, so message at index 65 should be NOT acked
        // The buggy code: 1L << 65 wraps to 1L << 1 = 2
        // So buggy code: (2L & 2) == 0 -> false (WRONG - says it's acked)
        // Correct: bit 65 is not set -> true (not acked)
        assertTrue("Message at index 65 should be not-acked since bit 65 is not set",
                orderInfo.isNotAck(65));
    }

    /**
     * Test that isNotAck returns false for index 0 when bit 0 is set (normal case).
     * This verifies the basic case still works.
     */
    @Test
    public void testIsNotAckAtIndex0WithBit0Set() {
        QueueLevelConsumerManager.OrderInfo orderInfo = new QueueLevelConsumerManager.OrderInfo();
        orderInfo.setCommitOffsetBit(1L);

        // Bit 0 IS set, so message at index 0 should be acked (not not-acked)
        assertFalse("Message at index 0 should be acked since bit 0 is set",
                orderInfo.isNotAck(0));
    }

    /**
     * Test that isNotAck returns true for all indices 0-63 when commitOffsetBit is 0.
     * All messages should be not-acked.
     */
    @Test
    public void testIsNotAckAllIndicesWhenNoBitsSet() {
        QueueLevelConsumerManager.OrderInfo orderInfo = new QueueLevelConsumerManager.OrderInfo();
        orderInfo.setCommitOffsetBit(0L);

        for (int i = 0; i < 64; i++) {
            assertTrue("Message at index " + i + " should be not-acked",
                    orderInfo.isNotAck(i));
        }
        // Also check indices >= 64 - these should also be not-acked
        // but the buggy code may wrap and give wrong results
        assertTrue("Message at index 64 should be not-acked",
                orderInfo.isNotAck(64));
        assertTrue("Message at index 100 should be not-acked",
                orderInfo.isNotAck(100));
    }

    /**
     * Test that isNotAck correctly identifies bit 63 (the highest valid bit in a long).
     */
    @Test
    public void testIsNotAckAtIndex63() {
        QueueLevelConsumerManager.OrderInfo orderInfo = new QueueLevelConsumerManager.OrderInfo();
        // Set bit 63 only (highest bit in a long)
        orderInfo.setCommitOffsetBit(1L << 63);

        // Bit 63 IS set, so message at index 63 should be acked
        assertFalse("Message at index 63 should be acked since bit 63 is set",
                orderInfo.isNotAck(63));

        // Bit 0 is NOT set, so message at index 0 should be not-acked
        assertTrue("Message at index 0 should be not-acked since bit 0 is not set",
                orderInfo.isNotAck(0));
    }

    /**
     * Test that isNotAck returns true for index 64 even when commitOffsetBit is all 1s
     * (all 64 bits of the long are set). Bit 64 is still outside the long range.
     * 
     * Bug: 1L << 64 wraps to 1, so the buggy code checks bit 0 which IS set,
     * returning false (acked) when it should return true (not acked).
     */
    @Test
    public void testIsNotAckAtIndex64WhenAll64BitsSet() {
        QueueLevelConsumerManager.OrderInfo orderInfo = new QueueLevelConsumerManager.OrderInfo();
        // Set all 64 bits of commitOffsetBit to 1 (every bit 0-63 is acked)
        orderInfo.setCommitOffsetBit(-1L); // all 1s in two's complement

        // Bit 64 is NOT in the long at all - it's outside the 64-bit range
        // So message at index 64 should NOT be acked
        // Buggy code: 1L << 64 wraps to 1L << 0 = 1, (-1L & 1) != 0 -> false (WRONG)
        // Correct: bit 64 doesn't exist in the long -> true (not acked)
        assertTrue("Message at index 64 should be not-acked since only bits 0-63 are set",
                orderInfo.isNotAck(64));
    }
}

