package org.apache.rocketmq.tools.command.consumer;

import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Tests for the GroupConsumeInfo.compareTo() overflow bug.
 *
 * The actual GroupConsumeInfo class is package-private and cannot be loaded
 * because the full Maven build cannot resolve dependencies from Nexus.
 *
 * This test embeds the EXACT compareTo() implementation from
 * ConsumerProgressSubCommand.java:347-352 to reproduce the overflow bug:
 *
 *   @Override
 *   public int compareTo(GroupConsumeInfo o) {
 *       if (this.count != o.count) {
 *           return o.count - this.count;
 *       }
 *       return (int) (o.diffTotal - diffTotal);
 *   }
 *
 * The bug: (int)(o.diffTotal - diffTotal) overflows when diffTotal values are
 * at opposite ends of the long range, producing incorrect ordering.
 */
public class GroupConsumeInfoCompareToTest {

    /**
     * Minimal standalone class with the EXACT same compareTo() implementation
     * from ConsumerProgressSubCommand.java:347-352, plus the fields needed
     * to reach the diffTotal comparison branch.
     */
    static class GroupConsumeInfo implements Comparable<GroupConsumeInfo> {
        private int count;
        private long diffTotal;

        public void setCount(int count) {
            this.count = count;
        }

        public void setDiffTotal(long diffTotal) {
            this.diffTotal = diffTotal;
        }

        public long getDiffTotal() {
            return diffTotal;
        }

        public int getCount() {
            return count;
        }

        @Override
        public int compareTo(GroupConsumeInfo o) {
            if (this.count != o.count) {
                return o.count - this.count;
            }

            // BUG: this subtraction overflows for extreme long values!
            // The correct implementation would be:
            //   return Long.compare(o.diffTotal, diffTotal);
            return (int) (o.diffTotal - diffTotal);
        }
    }

    /**
     * When counts are equal, compareTo should order by diffTotal descending.
