        AllocateMessageQueueByMachineRoomTest test = new AllocateMessageQueueByMachineRoomTest();
        boolean allPassed = true;
        try {
            test.testAllocateMessageQueueByMachineRoom();
            System.out.println("testAllocateMessageQueueByMachineRoom: PASS");
        } catch (Exception e) {
            System.out.println("testAllocateMessageQueueByMachineRoom: FAIL - " + e.getMessage());
            allPassed = false;
        }
        try {
            test.testAllocateNpeWhenConsumeridcsIsNull();
            System.out.println("testAllocateNpeWhenConsumeridcsIsNull: PASS");
        } catch (Exception e) {
            System.out.println("testAllocateNpeWhenConsumeridcsIsNull: FAIL - " + e.getMessage());
            allPassed = false;
        }
        if (!allPassed) {
            System.exit(1);
        }
        System.out.println("All tests passed.");
        System.exit(0);
    }

    public void testAllocateNpeWhenConsumeridcsIsNull() {
        List<String> consumerIdList = createConsumerIdList(2);
        List<MessageQueue> messageQueueList = createMessageQueueList(10);
        // Deliberately NOT calling setConsumeridcs() - consumeridcs stays null
        AllocateMessageQueueByMachineRoom allocateStrategy = new AllocateMessageQueueByMachineRoom();

        // This should NOT throw NPE; the correct behavior is to return empty result or handle gracefully
        try {
            List<MessageQueue> result = allocateStrategy.allocate("", consumerIdList.get(0), messageQueueList, consumerIdList);
            // If we get here without NPE, the method handled null consumeridcs gracefully
            // (The correct behavior: either return empty list or skip brokers without matching room)
            if (result != null) {
                System.out.println("allocate() returned without NPE, result size: " + result.size());
            }
        } catch (NullPointerException e) {
            // Bug: NPE is thrown because consumeridcs is null
            throw new AssertionError("NullPointerException thrown when consumeridcs is not initialized - the class should handle null consumeridcs gracefully", e);
        }
    }

    public void testAllocateMessageQueueByMachineRoom() {
        List<String> consumerIdList = createConsumerIdList(2);
        List<MessageQueue> messageQueueList = createMessageQueueList(10);
        Set<String> consumeridcs = new HashSet<>();
        consumeridcs.add("room1");
        AllocateMessageQueueByMachineRoom allocateStrategy = new AllocateMessageQueueByMachineRoom();
        allocateStrategy.setConsumeridcs(consumeridcs);

        // mqAll is null or mqAll empty
        try {
            allocateStrategy.allocate("", consumerIdList.get(0), new ArrayList<>(), consumerIdList);
        } catch (Exception e) {
            assert e instanceof IllegalArgumentException;
            if (!"mqAll is null or mqAll empty".equals(e.getMessage())) throw new AssertionError("Expected 'mqAll is null or mqAll empty' but got: " + e.getMessage());
        }

        Map<String, int[]> consumerAllocateQueue = new HashMap<>(consumerIdList.size());
        for (String consumerId : consumerIdList) {
            List<MessageQueue> queues = allocateStrategy.allocate("", consumerId, messageQueueList, consumerIdList);
            int[] queueIds = new int[queues.size()];
            for (int i = 0; i < queues.size(); i++) {
                queueIds[i] = queues.get(i).getQueueId();
            }
            consumerAllocateQueue.put(consumerId, queueIds);
        }
        if (!java.util.Arrays.equals(new int[] {0, 1, 4}, consumerAllocateQueue.get("CID_PREFIX0"))) throw new AssertionError("CID_PREFIX0 mismatch");
        if (!java.util.Arrays.equals(new int[] {2, 3}, consumerAllocateQueue.get("CID_PREFIX1"))) throw new AssertionError("CID_PREFIX1 mismatch");
    }

    private List<String> createConsumerIdList(int size) {
        List<String> consumerIdList = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            consumerIdList.add("CID_PREFIX" + i);
        }
        return consumerIdList;
    }

    private List<MessageQueue> createMessageQueueList(int size) {
        List<MessageQueue> messageQueueList = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            MessageQueue mq;
            if (i < size / 2) {
                mq = new MessageQueue("topic", "room1@broker-a", i);
            } else {
                mq = new MessageQueue("topic", "room2@broker-b", i);
            }
            messageQueueList.add(mq);
        }
        return messageQueueList;
    }
}

